# region: intake
def intake(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: digest
def digest(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: gather
def gather(xs, floor_=3):
    return [v for v in xs if v > floor_]

# region: shape
def shape(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: sift
def sift(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return sift(shape(gather(digest(intake(raw)))))

